#!/usr/bin/env bash
# Regenerates server/internal/protocol (Go) and client/src/protocol (TypeScript)
# from protocol/schema. Run via `make protocol`. Output is deterministic.
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$root"

command -v flatc >/dev/null || { echo "flatc not found; install flatbuffers" >&2; exit 1; }

schema=protocol/schema/lush.fbs
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

flatc --go -o "$tmp/go" "$schema"
flatc --ts -o "$tmp/ts" "$schema"

# Replace previously generated files only; hand-written files (tests) stay.
mkdir -p server/internal/protocol client/src/protocol
for f in server/internal/protocol/*.go; do
  [ -e "$f" ] && grep -q "Code generated by the FlatBuffers compiler" "$f" && rm -- "$f"
done
for f in client/src/protocol/*.ts; do
  [ -e "$f" ] && grep -q "automatically generated by the FlatBuffers compiler" "$f" && rm -- "$f"
done
cp "$tmp"/go/protocol/*.go server/internal/protocol/
cp "$tmp"/ts/protocol/*.ts client/src/protocol/

# Barrel file so the client imports everything from "./protocol/index.js".
{
  echo "// automatically generated by the FlatBuffers compiler, do not modify"
  for f in "$tmp"/ts/protocol/*.ts; do
    n="$(basename "$f" .ts)"
    grep -oE '^export (class|enum) [A-Za-z0-9_]+' "$f" | awk -v n="$n" '{print "export { " $3 " } from \x27./" n ".js\x27;"}'
  done
} > client/src/protocol/index.ts
